        address _from,
        address _to,
        uint256 _amount
    ) external {
        (bool success, ) = proxy.call(
            abi.encodeWithSignature(
                "transferFrom(address,address,uint256)",
                _from,
                _to,
                _amount
            )
        );
        require(success, "transferFrom failed");
    }
}

